<section class="page-header"><div><span class="eyebrow">Attendance-based salary processing</span><h1>Payroll</h1><p>Configurable calculations, approvals, locking and salary slips.</p></div><?php if(can('payroll.create')):?><div class="page-actions"><button class="button button-primary" data-modal-open="payrollModal"><i class="fa-solid fa-calculator"></i> Generate payroll</button></div><?php endif;?></section>
<div class="payroll-layout"><aside class="panel period-list"><div class="panel-head"><div><h2>Payroll periods</h2><p>Select a month</p></div></div><?php foreach($periods as $period):?><a href="<?= url('payroll?period='.$period['id']) ?>" class="period-row <?= $selected===$period['id']?'active':'' ?>"><div><strong><?= e(date('F Y',strtotime($period['period_month']))) ?></strong><small><?= (int)$period['staff_count'] ?> staff · <?= money($period['net_total']) ?></small></div><span class="status-badge <?= status_class($period['status']) ?>"><?= e($period['status']) ?></span></a><?php endforeach;?></aside><section class="panel table-panel payroll-table"><div class="panel-head"><div><h2>Salary calculation</h2><p>Individual attendance and deduction breakdown</p></div><?php if($selected&&can('payroll.approve')):?><form method="post" action="<?= url('payroll/'.$selected.'/status') ?>" class="inline-form"><?= csrf_field() ?><select name="status"><?php foreach(['Draft','Calculated','Under Review','Approved','Paid','Locked'] as $s):?><option><?= e($s) ?></option><?php endforeach;?></select><button class="button button-secondary button-sm">Update status</button></form><?php endif;?></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Staff</th><th>Present</th><th>Absent</th><th>Late</th><th>Gross</th><th>Deductions</th><th>Net salary</th><th>Slip</th></tr></thead><tbody><?php foreach($entries as $entry):?><tr><td><strong><?= e($entry['name']) ?></strong><small class="cell-sub"><?= e($entry['employee_code']) ?></small></td><td><?= e($entry['present_days']) ?></td><td><?= e($entry['absent_days']) ?></td><td><?= (int)$entry['late_count'] ?></td><td><?= money($entry['gross_pay']) ?></td><td class="text-danger"><?= money($entry['total_deduction']) ?></td><td><strong class="text-success"><?= money($entry['net_pay']) ?></strong></td><td><a class="icon-button" href="<?= url('salary-slips/'.$entry['id'].'?format=pdf') ?>"><i class="fa-solid fa-file-pdf"></i></a></td></tr><?php endforeach;?><?php if(!$entries):?><tr><td colspan="8"><div class="empty-state"><span><i class="fa-solid fa-money-check-dollar"></i></span><h3>No payroll entries</h3><p>Generate payroll for a month to calculate salaries.</p></div></td></tr><?php endif;?></tbody></table></div></section></div>
<dialog class="modal" id="payrollModal"><form method="post" action="<?= url('payroll/generate') ?>"><?= csrf_field() ?><div class="modal-head"><div><h3>Generate monthly payroll</h3><p>Existing draft calculations for the month will be refreshed.</p></div><button type="button" data-modal-close>×</button></div><div class="modal-body form-grid"><label>Payroll month<input type="month" name="month" value="<?= date('Y-m') ?>" required></label><label>Payable working days<input type="number" name="working_days" value="26" min="1" max="31" required></label><div class="inline-alert info wide"><i class="fa-solid fa-circle-info"></i> Approved, paid and locked periods cannot be recalculated.</div></div><div class="form-actions"><button type="button" class="button button-secondary" data-modal-close>Cancel</button><button class="button button-primary">Calculate payroll</button></div></form></dialog>
